package com.lankawings.servlet;
import com.lankawings.dao.*;import com.lankawings.util.Req;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{@Override protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(Req.isAdmin(r)){s.sendRedirect(r.getContextPath()+"/admin/tickets");return;}try{int uid=Req.uid(r);BookingDAO b=new BookingDAO();r.setAttribute("reservationCount",b.countForUser(uid));r.setAttribute("pendingCount",b.countPendingPaymentForUser(uid));r.setAttribute("confirmedCount",b.countConfirmedForUser(uid));r.setAttribute("ticketCount",new TicketDAO().countForUser(uid));r.setAttribute("nextFlights",new FlightDAO().next(4));}catch(Exception e){Req.error(r,e);}r.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(r,s);}}
